/* Dark theme (default) */
:root {
    --background: #1e1e1e;
    --foreground: #cccccc;
    --sidebar-background: #252526;
    --input-background: #3c3c3c;
    --border-color: #3c3c3c;
    --primary-color: #007acc;
    --hover-color: #2a2d2e;
    --focus-border: #007acc;
    --error-color: #f44336;
    --success-color: #4caf50;
    --warning-color: #ff9800;
    --text-muted: #888888;
    --scrollbar-thumb: #555555;
    --scrollbar-thumb-hover: #666666;
    /* BPMN element colors for dark theme */
    --bpmn-stroke: #d0d0d0;
    --bpmn-fill: #2d2d2d;
    --bpmn-text: #e0e0e0;
    --bpmn-stroke-hover: #4fc3f7;
    --bpmn-stroke-selected: #007acc;
    --bpmn-connection-stroke: #ffffff;
}

/* Light theme */
body.light-theme {
    --background: #ffffff;
    --foreground: #333333;
    --sidebar-background: #f3f3f3;
    --input-background: #ffffff;
    --border-color: #d4d4d4;
    --primary-color: #007acc;
    --hover-color: #e8e8e8;
    --focus-border: #007acc;
    --error-color: #d32f2f;
    --success-color: #388e3c;
    --warning-color: #f57c00;
    --text-muted: #666666;
    --scrollbar-thumb: #c1c1c1;
    --scrollbar-thumb-hover: #a8a8a8;
    /* BPMN element colors for light theme */
    --bpmn-stroke: #333333;
    --bpmn-fill: #ffffff;
    --bpmn-text: #333333;
    --bpmn-stroke-hover: #1976d2;
    --bpmn-stroke-selected: #007acc;
    --bpmn-connection-stroke: #555555;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body, #root {
    width: 100%;
    height: 100%;
    overflow: hidden;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    font-size: 13px;
    background: var(--background);
    color: var(--foreground);
}

.app-container {
    display: flex;
    flex-direction: column;
    height: 100%;
}

/* Toolbar */
.toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px;
    background: var(--sidebar-background);
    border-bottom: 1px solid var(--border-color);
    flex-shrink: 0;
}

.toolbar-group {
    display: flex;
    align-items: center;
    gap: 4px;
}

.toolbar-separator {
    width: 1px;
    height: 20px;
    background: var(--border-color);
    margin: 0 8px;
}

.toolbar-button {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border: none;
    background: transparent;
    color: var(--foreground);
    cursor: pointer;
    border-radius: 4px;
    transition: background 0.15s;
}

.toolbar-button:hover {
    background: var(--hover-color);
}

.toolbar-button:active {
    background: var(--primary-color);
}

.toolbar-button.active {
    background: var(--primary-color);
}

.toolbar-button svg {
    width: 16px;
    height: 16px;
}

.file-info {
    margin-left: auto;
    font-size: 12px;
    color: var(--text-muted);
}

.file-info .dirty-indicator {
    color: var(--warning-color);
    margin-right: 4px;
}

/* Main Content Area */
.main-content {
    display: flex;
    flex: 1;
    overflow: hidden;
}

/* Palette (Left Sidebar) */
.palette {
    width: 280px;
    background: var(--sidebar-background);
    border-right: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
}

.palette-header {
    padding: 10px 12px;
    border-bottom: 1px solid var(--border-color);
}

.palette-search {
    width: 100%;
    padding: 6px 10px;
    background: var(--input-background);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    color: var(--foreground);
    font-size: 12px;
}

.palette-search:focus {
    outline: none;
    border-color: var(--focus-border);
}

.palette-content {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.category {
    margin-bottom: 4px;
}

.category-header {
    display: flex;
    align-items: center;
    padding: 6px 12px;
    cursor: pointer;
    user-select: none;
    font-weight: 500;
    font-size: 12px;
}

.category-header:hover {
    background: var(--hover-color);
}

.category-icon {
    width: 16px;
    height: 16px;
    margin-right: 8px;
    transition: transform 0.15s;
}

.category-icon.collapsed {
    transform: rotate(-90deg);
}

.category-badge {
    display: inline-block;
    padding: 2px 6px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 500;
    margin-left: auto;
}

.delegate-list {
    padding-left: 24px;
}

.delegate-item {
    padding: 6px 12px;
    cursor: grab;
    border-radius: 4px;
    margin: 2px 8px;
    font-size: 12px;
    transition: background 0.15s;
}

.delegate-item:hover {
    background: var(--hover-color);
}

.delegate-item:active {
    cursor: grabbing;
}

.delegate-name {
    font-weight: 500;
}

.delegate-expression {
    font-family: monospace;
    font-size: 10px;
    color: var(--text-muted);
    margin-top: 2px;
}

/* Editor Canvas */
.editor-canvas {
    flex: 1;
    position: relative;
    overflow: hidden;
}

.bpmn-container {
    width: 100%;
    height: 100%;
}

/* Properties Panel (Right Sidebar) */
.properties-panel {
    width: 300px;
    background: var(--sidebar-background);
    border-left: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    overflow-y: auto;
}

.properties-header {
    padding: 10px 12px;
    border-bottom: 1px solid var(--border-color);
    font-weight: 500;
}

.properties-content {
    padding: 12px;
}

.property-group {
    margin-bottom: 16px;
}

.property-group-title {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 8px;
}

.property-row {
    margin-bottom: 12px;
}

.property-label {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 4px;
}

.property-value {
    font-size: 13px;
}

.property-input {
    width: 100%;
    padding: 6px 10px;
    background: var(--input-background);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    color: var(--foreground);
    font-size: 12px;
}

.property-input:focus {
    outline: none;
    border-color: var(--focus-border);
}

.property-input:read-only {
    background: transparent;
    border-color: transparent;
}

.delegate-select {
    width: 100%;
    padding: 6px 10px;
    background: var(--input-background);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    color: var(--foreground);
    font-size: 12px;
    cursor: pointer;
}

.delegate-info {
    padding: 8px;
    background: var(--input-background);
    border-radius: 4px;
    margin-top: 8px;
}

.delegate-info-row {
    display: flex;
    align-items: center;
    margin-bottom: 4px;
    font-size: 12px;
}

.delegate-info-label {
    color: var(--text-muted);
    min-width: 80px;
}

.open-source-btn {
    padding: 4px 8px;
    background: var(--primary-color);
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 11px;
    cursor: pointer;
    margin-top: 8px;
}

.open-source-btn:hover {
    opacity: 0.9;
}

.variables-section {
    margin-top: 12px;
}

.variables-title {
    font-size: 11px;
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 6px;
}

.variable-item {
    display: flex;
    align-items: center;
    font-size: 11px;
    padding: 4px 0;
}

.variable-name {
    font-family: monospace;
    color: var(--primary-color);
    margin-right: 6px;
}

.variable-type {
    color: var(--text-muted);
}

.variable-required {
    color: var(--error-color);
    font-size: 10px;
    margin-left: 4px;
}

/* Empty State */
.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: var(--text-muted);
    font-size: 14px;
}

.empty-state-icon {
    font-size: 48px;
    margin-bottom: 16px;
    opacity: 0.5;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb);
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--scrollbar-thumb-hover);
}

/* bpmn-js overrides */
.bjs-powered-by {
    display: none !important;
}

/* Hide default palette - we use our own ComponentPalette */
.djs-palette {
    display: none !important;
}

/* ========================================
   BPMN-JS Theme Styles
   Note: Main colors are now set via bpmnRenderer options
   CSS here is for additional styling and overrides
   ======================================== */

/* Canvas 背景 */
.djs-container {
    background: var(--background) !important;
}

/* 選中的元素外框 - 加強高亮 */
.djs-shape.selected .djs-outline,
.djs-connection.selected .djs-outline {
    stroke: var(--bpmn-stroke-selected) !important;
    stroke-width: 2px !important;
}

/* 滑鼠懸停高亮 */
.djs-shape.hover .djs-outline {
    stroke: var(--bpmn-stroke-hover) !important;
    stroke-width: 1.5px !important;
    visibility: visible !important;
}

/* 選取框 */
.djs-outline {
    stroke: var(--bpmn-stroke-selected) !important;
    stroke-width: 1px !important;
}

/* 拖曳時的預覽 */
.djs-dragging .djs-visual > * {
    opacity: 0.7;
}

/* ========================================
   Context Pad and Popup Styling
   ======================================== */

/* Context pad styling - Dark theme (default) */
.djs-context-pad {
    z-index: 100;
}

.djs-context-pad .entry {
    display: flex !important;
    align-items: center;
    justify-content: center;
    background: var(--sidebar-background);
    border: 1px solid var(--border-color);
    border-radius: 4px;
}

.djs-context-pad .entry:hover {
    background: var(--hover-color);
}

/* Popup menu styling */
.djs-popup {
    z-index: 200;
    background: var(--sidebar-background) !important;
    border: 1px solid var(--border-color) !important;
    border-radius: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.djs-popup .entry {
    cursor: pointer;
    color: var(--foreground);
}

.djs-popup .entry:hover {
    background: var(--hover-color);
}

.djs-popup .djs-popup-header {
    background: var(--sidebar-background);
    border-bottom: 1px solid var(--border-color);
    color: var(--foreground);
}

.djs-popup .djs-popup-body {
    background: var(--sidebar-background);
}

/* ========================================
   Light Theme Specific Overrides
   ======================================== */

body.light-theme .djs-popup {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}
